INSERT INTO glossary_terms (term_key, term, aliases, definition, source, verified) VALUES
  ($g$hiperglikemia$g$, $g$Hiperglikemia$g$, ARRAY[$g$gula darah tinggi$g$,$g$glukosa darah tinggi$g$]::text[], $g$Kadar glukosa darah yang tinggi atau berlebih. Paling sering terjadi pada diabetes dan prediabetes, ketika tubuh kekurangan insulin atau tidak dapat memakainya secara efektif; dapat pula muncul pada kondisi lain seperti sindrom Cushing. Tanda klasiknya haus berlebihan (polidipsia), sering buang air kecil (poliuria), dan mulut kering. Gejala biasanya baru muncul setelah glukosa mencapai sekitar 180–200 mg/dL ke atas. Bila berlangsung lama, hiperglikemia dapat merusak saraf, pembuluh darah, dan organ, serta dapat berujung pada ketoasidosis.$g$, $g$American Diabetes Association (daftar istilah diabetes); RxList — Definition of Hyperglycemia; Flushing Hospital Medical Center (mengutip Mayo Clinic); diringkas ke bahasa Indonesia$g$, false),
  ($g$hipokalemia$g$, $g$Hipokalemia$g$, ARRAY[$g$kalium rendah$g$,$g$kadar kalium darah rendah$g$]::text[], $g$Keadaan ketika kadar kalium dalam darah lebih rendah dari normal (rentang acuan sekitar 3,6–5,2 mmol/L menurut Mayo Clinic). Penyebab tersering adalah kehilangan kalium lewat urin akibat obat yang meningkatkan buang air kecil (diuretik). Muntah, diare, kadar magnesium rendah, dan asupan yang kurang juga dapat menjadi penyebab. Penurunan kecil sering tidak bergejala, sedangkan penurunan besar dapat menimbulkan gangguan irama jantung yang berbahaya, terutama pada penyakit jantung. Penanganan bergantung pada penyebab dan dapat berupa suplemen kalium, secara intravena pada kasus berat.$g$, $g$MedlinePlus (NLM) — Low blood potassium; Mayo Clinic — Low potassium (hypokalemia); diringkas ke bahasa Indonesia$g$, false),
  ($g$hiponatremia$g$, $g$Hiponatremia$g$, ARRAY[$g$natrium rendah$g$,$g$kadar natrium darah rendah$g$]::text[], $g$Keadaan ketika kadar natrium dalam darah di bawah normal, yaitu kurang dari 135 mmol/L (mEq/L); rentang normal sekitar 135–145 mmol/L dan dapat sedikit berbeda antar laboratorium. Terjadi karena natrium tubuh menjadi encer oleh kelebihan air relatif, atau karena kehilangan natrium lebih besar daripada air. Berdasarkan status cairan tubuh dibedakan menjadi hipovolemik, euvolemik, dan hipervolemik. Sel otak sangat peka terhadap pembengkakan sehingga banyak gejalanya bersifat neurologis. Hiponatremia akut (kurang dari 48 jam) lebih berbahaya daripada yang berkembang perlahan (kronik).$g$, $g$MedlinePlus (NLM) — Low blood sodium; Mayo Clinic — Hyponatremia; diringkas ke bahasa Indonesia$g$, false)
